-- Facility override layers (owned by the agency)
delete from public.requirements where requirement_set_id = md5('veridun:set:facility:houston-rapid')::uuid;
delete from public.requirements where requirement_set_id = md5('veridun:set:facility:phoenix-ed')::uuid;
delete from public.requirements where requirement_set_id = md5('veridun:set:facility:denver-ld')::uuid;

on conflict (id) do nothing;
 select md5('veridun:assignment:boston-icu')::uuid, id from public.requirement_sets where (owner_org_id is null and layer = 'STATE' and key = 'US-MA') or (owner_org_id is null and layer = 'WORK_TYPE' and key = 'TRAVEL_RN') or (owner_org_id is null and layer = 'SPECIALTY' and key = 'ICU')
 union all
 select md5('veridun:assignment:houston-rapid')::uuid, id from public.requirement_sets where (owner_org_id is null and layer = 'STATE' and key = 'US-TX') or (owner_org_id is null and layer = 'WORK_TYPE' and key = 'RAPID_RESPONSE_RN') or (owner_org_id is null and layer = 'SPECIALTY' and key = 'ICU') or id = md5('veridun:set:facility:houston-rapid')::uuid
 union all
 select md5('veridun:assignment:oakland-strike')::uuid, id from public.requirement_sets where (owner_org_id is null and layer = 'STATE' and key = 'US-CA') or (owner_org_id is null and layer = 'WORK_TYPE' and key = 'STRIKE_RN') or (owner_org_id is null and layer = 'SPECIALTY' and key = 'ICU') or (owner_org_id is null and layer = 'SPECIALTY' and key = 'ED') or (owner_org_id is null and layer = 'SPECIALTY' and key = 'LD')
 union all
 select md5('veridun:assignment:phoenix-ed')::uuid, id from public.requirement_sets where (owner_org_id is null and layer = 'STATE' and key = 'US-AZ') or (owner_org_id is null and layer = 'WORK_TYPE' and key = 'TRAVEL_RN') or (owner_org_id is null and layer = 'SPECIALTY' and key = 'ED') or id = md5('veridun:set:facility:phoenix-ed')::uuid
 union all
 select md5('veridun:assignment:denver-ld')::uuid, id from public.requirement_sets where (owner_org_id is null and layer = 'STATE' and key = 'US-CO') or (owner_org_id is null and layer = 'WORK_TYPE' and key = 'PER_DIEM_RN') or (owner_org_id is null and layer = 'SPECIALTY' and key = 'LD') or id = md5('veridun:set:facility:denver-ld')::uuid
