-- Demo credentials (VERIFIED by the simulated source — DEMO, not a real verification)
on conflict (id) do nothing;
select c.id, (select id from public.verification_sources where method = 'SIMULATED_PRIMARY_SOURCE' limit 1), 'SIMULATED_PRIMARY_SOURCE', 'SUCCEEDED',
       now() - interval '1 day', now() - interval '1 day', 0, false, 'DEMO SEED (not a real verification)'
  from public.credentials c join public.clinicians k on k.id = c.clinician_id
 where k.is_demo and not exists (select 1 from public.credential_verifications v where v.credential_id = c.id);

select 'DEMO_SEEDED', 'SYSTEM', k.id, 'DEMO', jsonb_build_object('credentials', (select count(*) from public.credentials c where c.clinician_id = k.id))
  from public.clinicians k where k.is_demo
   and not exists (select 1 from public.audit_events e where e.event_type = 'DEMO_SEEDED' and e.clinician_id = k.id);

commit;
